function OverseaManageMainDialog:AddEventListener()
    self:RemoveListener()
    self.onServerFinishEvent = Events.AddListener(MaidCoffeeConstants.EventNames.MaidCoffeeServerFinishEvents, Bind(self, self.ServerFinishEvent))
    self.onEventRefreshEvent = Events.AddListener(MaidCoffeeConstants.EventNames.MaidCoffeeRefreshGuestEventsComplete, Bind(self, self.ServerFinishEvent))
    self.openPcTipsEvent = Events.AddListener(MaidCoffeeConstants.EventNames.MaidCoffeeOpenPcTips, Bind(self, self.OnOpenPcTip))
