end

function OverseaManageMainDialog:RemoveListener()
    if self.onServerFinishEvent then
        Events.RemoveListener(MaidCoffeeConstants.EventNames.MaidCoffeeServerFinishEvents, self.onServerFinishEvent)
        self.onServerFinishEvent = nil
    end

    if self.onEventRefreshEvent then
        Events.RemoveListener(MaidCoffeeConstants.EventNames.MaidCoffeeRefreshGuestEventsComplete, self.onEventRefreshEvent)
        self.onEventRefreshEvent = nil
    end

    if self.openPcTipsEvent then
        Events.RemoveListener(MaidCoffeeConstants.EventNames.MaidCoffeeOpenPcTips, self.openPcTipsEvent)
        self.openPcTipsEvent = nil
    end

    if self.onRequestGuestSuccess then
        Events.RemoveListener(MaidCoffeeConstants.EventNames.MaidCoffeeRequestGuestSuccess, self.onRequestGuestSuccess)
        self.onRequestGuestSuccess = nil
    end
end

function OverseaManageMainDialog:ServerFinishEvent()
