end

function OverseaManageMainDialog:OnOpenPcTip()
    local isPcOpen = checkNumber(CfUtils.CookieLoad("MapDecryptionPCTipsDialogOpen"))
    ---说明是开着的
    if isPcOpen == 0 then
        MaidCoffeeUtils.EnterPCTipsDialog()
    else
        Events.Broadcast(MaidCoffeeConstants.EventNames.MaidCoffeeClosePcTip)
    end
end

function OverseaManageMainDialog:InitGuestEnv()
    if self.DailyCustomerPanel then
        local env = CfUtils.GetLuaScr(self.DailyCustomerPanel, "Game.MaidCoffee.MaidCoffeeGuestUIDialog.MaidCoffeeDailyEventController")
        if not isNull(env) then
            self.guestEnv = env
        end
    end
end

function OverseaManageMainDialog:SetButtonState()
    if GameUtils.IsPCPlatform() then
        KTool.SetActive(self.BtnTips.gameObject, true)
    else
        KTool.SetActive(self.BtnTips.gameObject, false)
    end

    local isRenovaUnLock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id3012)
    KTool.SetActive(self.BtnRenovaLock, not isRenovaUnLock)
    local alpha = isRenovaUnLock and 1 or 0.5
    self:SetBtnCanvasAlpha(self.BtnRenova, alpha)

    if isRenovaUnLock then
        local maidCoffeeComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
        local isHaveRedPoint = maidCoffeeComponent:IsShowAvatarsNew()
        KTool.SetActive(self.RenovaNew.gameObject, isHaveRedPoint)
    else
        KTool.SetActive(self.RenovaNew.gameObject, false)
    end

    local isCustomerUnLock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id3016)
    KTool.SetActive(self.BtnCustomerLock, not isCustomerUnLock)
    local alpha = isCustomerUnLock and 1 or 0.5
    self:SetBtnCanvasAlpha(self.BtnCustomer, alpha)

    local isCallOnUnLock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id266)
    KTool.SetActive(self.BtnCallOnLock, not isCallOnUnLock)
    local alpha = isCallOnUnLock and 1 or 0.5
    self:SetBtnCanvasAlpha(self.BtnCallOn, alpha)

end

function OverseaManageMainDialog:SetBtnCanvasAlpha(btnGo, alpha)
    local CanvasGroup = CS.UnityEngine.CanvasGroup
    local go = btnGo.transform:Find("Pellucidity")
    if go then
        local canvasGroup = go.gameObject:GetComponent(typeof(CanvasGroup))
        if canvasGroup then
            if math.floor(canvasGroup.alpha) ~= alpha then
                canvasGroup.alpha = alpha
            end
        end
    end
end

function OverseaManageMainDialog:OnFocus(focus)
    if focus then
        Events.Broadcast("MaidCoffeeChangeRoleStatus",true)
    end
end

function OverseaManageMainDialog:AddUIClick()
    SetButtonAction(self.BtnTips.gameObject, Bind(self, self.OnBtnTipsClick))
    SetButtonAction(self.BtnRenova.gameObject, Bind(self, self.OnBtnRenovaClick))
    SetButtonAction(self.BtnCustomer.gameObject, Bind(self, self.OnBtnCustomerClick))
    SetButtonAction(self.BtnCallOn.gameObject, Bind(self, self.OnBtnCallOnClick))
    SetButtonAction(self.BtnShiftOfPerspectives.gameObject, Bind(self, self.OnBtnShiftOfPerspectivesClick))
end

function OverseaManageMainDialog:OnShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        xTry(function()
            if GameUtils.IsPCPlatform() then
                MaidCoffeeUtils.MaidCoffeeSetMouseMode(Constants.CameraControlMode.None)
            else
                MaidCoffeeUtils.MaidCoffeeSetMouseMode(Constants.CameraControlMode.MoveMouse)
            end
            CinemachineBrainUtility.SetDefaultBlendDefinition(CinemachineBlendDefinition.Style.EaseInOut, MaidCoffeeConstants.VirtualCamTime)
            ---不显示假人
            Events.Broadcast("MaidCoffeeRefreshManagerStatus", false)
            Events.Broadcast("MaidCoffeeChangeRoleStatus", true, false)
            Events.Broadcast(MaidCoffeeConstants.EventNames.ClearRenovateState)
            cs_coroutine.yield_return(self:AutoOpenDialog())
        end)
    end))
    return coWait
end

function OverseaManageMainDialog:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        xTry(function()
            local maidCoffeeComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
            local maidCoffeeHomeDojo = maidCoffeeComponent:GetMaidCoffeeHomeDoJo()
            maidCoffeeHomeDojo:SetIsOther(false)
            self:RefreshShow()
            CS.UINavigationBarRoot.Instance:SetActive(true)
            CfUtils.RefreshTopGoods({})
        end)
    end))
    return coWait
end

function OverseaManageMainDialog:RefreshShow()
