end

function OverseaManageMainDialog:BindRedPoint()
    local isCustomerUnLock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id3016)
    if isCustomerUnLock then
        GameUtils.BindRedPoint(Constants.RedPointConst.MaidCafeCattyCollection, self.BtnCustomer, true)
    end

    local isCallOnUnLock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id266)
    if isCallOnUnLock then
        GameUtils.BindRedPoint(Constants.RedPointConst.MaidCafeCattyCallOn, self.BtnCallOn, true)
    end
end

function OverseaManageMainDialog:RemoveRedPoint()
    GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.MaidCafeCattyCollection)
    GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.MaidCafeCattyCallOn)
end

function OverseaManageMainDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        xTry(function()
            self.guestEnv:Delete()
            self._parameters = nil
            self.controller = nil --删除lua层引⽤到的c#对象否则不会产⽣c# gc回收到对象
            self:RemoveRedPoint()
            self:RemoveAutoCo()
            self:RemoveListener()
            self:Delete()
            self = nil --lua层的gc需要
        end)
    end))
    return coWait
end

function OverseaManageMainDialog:AutoOpenDialog()
    self._parameters = self.controller.Argument.parameters
    if not isNull(self._parameters.autoData) and isSet(self._parameters.autoData, "id") then
        local id = checkNumber(self._parameters.autoData.id)
        local data = self._parameters.autoData.data
        if id == Constants.UITypeIds.OverseaRenovaMainDialog then
            self:RemoveAutoCo()
            self.autoCo = cs_coroutine.start(function()
                coroutine.yield(CS.Engine.Lib.Yielders.GetWaitForSeconds(checkNumber(0.5)))
                MaidCoffeeUtils.MaidCoffeeSetMouseMode(Constants.CameraControlMode.None)
                CinemachineBrainUtility.SetDefaultBlendDefinition(CinemachineBlendDefinition.Style.EaseInOut, 0.5)
                cs_coroutine.yield_return(UIModule.OpenDialog({ id = Constants.UITypeIds.OverseaRenovaMainDialog , parameters = { data = data} }, { { id = Constants.UITypeIds.UIMaidCoffeeMainDialog } }))
            end)
        elseif id == Constants.UITypeIds.OverseaManageMerchantTalkingNode then
            Events.Broadcast(MaidCoffeeConstants.EventNames.MaidCoffeeGoToPosition,{type = "MaidCoffeeBusiness"})
        end
        self.controller.Argument.parameters.autoData = nil
    else
        if GuideUtils.IsInGuiding() then
            return
        end
        MaidCoffeeUtils.EnterMaidCoffeePopUp()
    end
end

function OverseaManageMainDialog:RemoveAutoCo()
    if not isNull(self.autoCo) then
        cs_coroutine.stop(self.autoCo)
        self.autoCo = nil
    end
end
